"""Publish two verified randomly drawn test animations, preserving existing reports."""
from pathlib import Path
import json,hashlib
from huggingface_hub import HfApi,hf_hub_download,CommitOperationAdd
R=Path(__file__).resolve().parent;D=R/'data/animations';selection=json.loads((D/'selection.json').read_text());assert selection['indices']==[1498,1598]
sections=[]
for c in selection['cases']:
 n=c['case'];assert (D/(n+'.gif')).stat().st_size>1000
 sections.append(f'<section><h2>{n} · wind {c["wind_m_s"]:g}m/s</h2><p>Test history {c["index"]}; crown height {c["crown_height_m"]:g}m above a2m base.</p><img src="{n}.gif" alt="Animated 3D actual gas temperature with reference and predicted cone"><p><a href="{n}.gif" download>Download GIF</a> · <a href="{n}.json">Displayed frame data</a></p></section>')
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Two random test cases · 3D cones and hot gas</title><style>body{font:17px/1.55 system-ui;background:#f3f5f8;color:#182637;margin:0}main{max-width:1250px;margin:auto;padding:25px}section{background:white;border-radius:12px;padding:20px;margin:20px 0}img{width:100%;height:auto}a{color:#205bb0}li{margin:.5em 0}</style><main><a href="../index.html">Experiment46 results</a><h1>Two randomly selected test cases in3D</h1><p>Reference cone on the left; selected model (epoch134) on the right. Both panels show the <strong>same actual simulated gas temperatures</strong>. Only the right cone is a neural prediction; the model does not predict a full temperature field.</p><ul><li>Cyan: extracted reference envelope. Magenta: predicted envelope. Green: fixed crown geometry,3m wide and8m tall above a2m base; no trunk or species detail.</li><li>Dots: saved cell-centre gas temperatures above50°C, coloured on a fixed50–1500°C scale. At most600 cells per frame are displayed, evenly sampled through the hot-cell indices plus the hottest cell. These dots are not embers or neural activations.</li><li>All91 saved frames span approximately0–180seconds; GIF playback is about16× faster than simulated time, with no interpolation or temporal smoothing. A prediction is unavailable at time0. Predicted cones are hidden below presence probability0.5.</li><li>The imposed1500°C igniter operates during the first20seconds. Hot gas includes this source; it is not exclusively heat from tree combustion. No buildings or embers;0.5m grid and24×16×16m observed crop.</li><li>These broad fitted cones aim for95% hot-cell coverage and often include much cooler space. Their apex is not a physical flame pivot. Peak temperature is instantaneous, not heat flux, received heat or an interval maximum. Cone geometry may extend beyond the observed crop.</li></ul><p>Selection: uniform random draw of two of the208 frozen test histories without replacement, NumPy seed20261102. No filtering on errors or appearance. Both draws happened to have8m crowns. This historically examined test set is not pristine confirmation.</p>'''+''.join(sections)+'<p><a href="selection.json">Selection and source provenance</a></p></main></html>'
(D/'index.html').write_text(html)
api=HfApi();repo='wdavies/fire-reports';rev=api.repo_info(repo,repo_type='space').sha
parent=Path(hf_hub_download(repo,'cone46/index.html',repo_type='space',revision=rev)).read_text();link='<p><a href="animations/index.html">Watch two random test cases: 3D cones and simulated hot gas →</a></p>'
assert link not in parent;updated=parent.replace('<h2>Five-chart gallery</h2>',link+'<h2>Five-chart gallery</h2>',1);assert updated.replace(link,'',1)==parent and updated!=parent
files={f'cone46/animations/{f.name}':f for f in D.iterdir() if f.is_file()}
ops=[CommitOperationAdd(path_in_repo=n,path_or_fileobj=str(f)) for n,f in files.items()];ops.append(CommitOperationAdd(path_in_repo='cone46/index.html',path_or_fileobj=updated.encode()))
c=api.create_commit(repo_id=repo,repo_type='space',parent_commit=rev,operations=ops,commit_message='Add two random held-out 3D cone and gas-temperature animations')
for n,f in files.items():assert Path(hf_hub_download(repo,n,repo_type='space',revision=c.oid)).read_bytes()==f.read_bytes()
assert Path(hf_hub_download(repo,'cone46/index.html',repo_type='space',revision=c.oid)).read_text()==updated
(R/'animation-publication.json').write_text(json.dumps(dict(commit=c.oid,readback_exact=True,previous_report_preserved=True,files={n:hashlib.sha256(f.read_bytes()).hexdigest() for n,f in files.items()}),indent=2)+'\n')
print('Published and verified',c.oid)
